"""AG-UI event builders for Copilot v2.

CUSTOM is AG-UI's extension point; every CUSTOM event this deployment emits is
documented here (the protocol docs direct teams to keep this list):

- ``commit_info``: end-of-run commit outcome (sha, commit details and the
  ``branch`` it landed on), emitted by the commit hook when a run changed
  project files.
- ``branch_created``: ``{"branch": <new>, "base": <branch it started from>}``,
  emitted by the orchestrator after each successful ``create_branch`` tool
  result.
- ``skill_loaded``: ``{"name", "use_case", "version"}`` of a Copilot skill,
  emitted by the orchestrator after each successful ``load_capability`` tool
  result. The load's own tool-call events are not streamed, because its result
  is the skill body. The thread store keeps the load as a ``role="skill"`` row
  with the same fields.
- ``plan_update`` — live checklist payload ``{"tasks": [...]}``, emitted by the
  orchestrator after each successful ``update_plan`` tool result.
- ``policy_violation`` — a guardrails-refused run's outcome. Host vocabulary:
  built in ``rasa.builder.copilot.preflight`` via the generic :func:`custom`
  builder; the runtime never learns it.
- ``message_metadata`` — ``{"response_category": <category>}``, emitted right
  after triage on both branches, so an agent-served turn carries it too.
  Present iff the classifier returned a category: runs with the classifier off,
  and turns whose triage raised, never carry it. Whether the category was
  served from a template is derivable from the value itself, since
  ``requires_full_copilot`` is a pure function of the category.

Every RUN_ERROR carries a ``code`` from ``RunErrorCode`` below plus a free-form
``message``. Downstream error-rate metrics (SWI-1376) group on the code, not on
the message and not on the exception class name, which shifts under dependency
upgrades.
"""

from __future__ import annotations

from enum import Enum
from typing import Any


class RunErrorCode(str, Enum):
    """Stable RUN_ERROR ``code`` vocabulary; see the module docstring."""

    TIMEOUT = "timeout"
    MAX_TURNS = "max_turns"
    MODEL_ERROR = "model_error"
    INVALID_REQUEST = "invalid_request"
    MISSING_USER_ID = "missing_user_id"
    RUNTIME_EXCEPTION = "runtime_exception"


def run_started(thread_id: str, run_id: str) -> dict[str, Any]:
    """Build an AG-UI RUN_STARTED event."""
    return {"type": "RUN_STARTED", "threadId": thread_id, "runId": run_id}


def run_finished(thread_id: str, run_id: str) -> dict[str, Any]:
    """Build an AG-UI RUN_FINISHED event."""
    return {"type": "RUN_FINISHED", "threadId": thread_id, "runId": run_id}


def run_error(message: str, code: RunErrorCode) -> dict[str, Any]:
    """Build an AG-UI RUN_ERROR event carrying a stable ``code``."""
    return {"type": "RUN_ERROR", "message": message, "code": code.value}


def text_message_start(message_id: str) -> dict[str, Any]:
    """Build an AG-UI TEXT_MESSAGE_START event."""
    return {
        "type": "TEXT_MESSAGE_START",
        "messageId": message_id,
        "role": "assistant",
    }


def text_message_content(message_id: str, delta: str) -> dict[str, Any]:
    """Build an AG-UI TEXT_MESSAGE_CONTENT event."""
    return {
        "type": "TEXT_MESSAGE_CONTENT",
        "messageId": message_id,
        "delta": delta,
    }


def text_message_end(message_id: str) -> dict[str, Any]:
    """Build an AG-UI TEXT_MESSAGE_END event."""
    return {"type": "TEXT_MESSAGE_END", "messageId": message_id}


def tool_call_start(tool_call_id: str, tool_name: str) -> dict[str, Any]:
    """Build an AG-UI TOOL_CALL_START event."""
    return {
        "type": "TOOL_CALL_START",
        "toolCallId": tool_call_id,
        "toolCallName": tool_name,
    }


def tool_call_args(tool_call_id: str, delta: str) -> dict[str, Any]:
    """Build an AG-UI TOOL_CALL_ARGS event.

    ``delta`` carries the tool-call arguments as a JSON string. The v2 runtime
    emits the complete argument JSON in a single event rather than incremental
    chunks.
    """
    return {
        "type": "TOOL_CALL_ARGS",
        "toolCallId": tool_call_id,
        "delta": delta,
    }


def tool_call_end(tool_call_id: str) -> dict[str, Any]:
    """Build an AG-UI TOOL_CALL_END event."""
    return {"type": "TOOL_CALL_END", "toolCallId": tool_call_id}


def tool_call_result(
    message_id: str,
    tool_call_id: str,
    content: str,
) -> dict[str, Any]:
    """Build an AG-UI TOOL_CALL_RESULT event.

    ``content`` is a JSON string. On success it is the tool's return value; on
    failure it is a stable error envelope (``{"error": "..."}``) so downstream
    consumers can count per-tool errors without the run aborting.
    """
    return {
        "type": "TOOL_CALL_RESULT",
        "messageId": message_id,
        "toolCallId": tool_call_id,
        "content": content,
    }


def custom(name: str, value: Any) -> dict[str, Any]:
    """Build an AG-UI CUSTOM event.

    CUSTOM is the protocol's extension point: the ``name`` names a host-defined
    event and ``value`` carries its payload. Keeping the constructor generic is
    what lets a host stream its own events (policy pre-flight outcomes, routing
    decisions) without the runtime learning that vocabulary.
    """
    return {"type": "CUSTOM", "name": name, "value": value}


def commit_info(value: dict[str, Any]) -> dict[str, Any]:
    """Build a CUSTOM commit_info event."""
    return custom("commit_info", value)


def plan_update(value: dict[str, Any]) -> dict[str, Any]:
    """Build a CUSTOM plan_update event.

    ``value`` is the full-plan wire payload ``{"tasks": [...]}`` — the same
    shape the todo-list UI already consumes and the persist path stores.
    """
    return custom("plan_update", value)


def branch_created(value: dict[str, Any]) -> dict[str, Any]:
    """Build a CUSTOM branch_created event.

    ``value`` is ``{"branch": ..., "base": ...}``: the branch the run now works
    on and the one it was created from.
    """
    return custom("branch_created", value)


def skill_loaded(*, name: str, use_case: str, version: str) -> dict[str, Any]:
    """Build a CUSTOM skill_loaded event for a Copilot skill the model loaded."""
    return custom(
        "skill_loaded", {"name": name, "use_case": use_case, "version": version}
    )


def message_metadata(response_category: str) -> dict[str, Any]:
    """Build a CUSTOM message_metadata event for a classifier-served turn."""
    return custom("message_metadata", {"response_category": response_category})


def reasoning_start(message_id: str) -> dict[str, Any]:
    """Build an AG-UI REASONING_START event."""
    return {"type": "REASONING_START", "messageId": message_id}


def reasoning_message_start(message_id: str) -> dict[str, Any]:
    """Build an AG-UI REASONING_MESSAGE_START event."""
    return {
        "type": "REASONING_MESSAGE_START",
        "messageId": message_id,
        "role": "reasoning",
    }


def reasoning_message_content(message_id: str, delta: str) -> dict[str, Any]:
    """Build an AG-UI REASONING_MESSAGE_CONTENT event."""
    return {
        "type": "REASONING_MESSAGE_CONTENT",
        "messageId": message_id,
        "delta": delta,
    }


def reasoning_message_end(message_id: str) -> dict[str, Any]:
    """Build an AG-UI REASONING_MESSAGE_END event."""
    return {"type": "REASONING_MESSAGE_END", "messageId": message_id}


def reasoning_end(message_id: str) -> dict[str, Any]:
    """Build an AG-UI REASONING_END event."""
    return {"type": "REASONING_END", "messageId": message_id}


def reasoning_encrypted_value(
    *,
    subtype: str,
    entity_id: str,
    encrypted_value: str,
) -> dict[str, Any]:
    """Build an AG-UI REASONING_ENCRYPTED_VALUE event."""
    return {
        "type": "REASONING_ENCRYPTED_VALUE",
        "subtype": subtype,
        "entityId": entity_id,
        "encryptedValue": encrypted_value,
    }
